import{_ as e,c as r,o as a,ai as n}from"./chunks/framework.B63Sb1io.js";const u=JSON.parse('{"title":"计算机网络的概念","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"计算机网络的概念","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/01/408_CN_1.md","filePath":"post/kaoyan/408/408_CN/01/408_CN_1.md","lastUpdated":1756268504000}'),o={name:"post/kaoyan/408/408_CN/01/408_CN_1.md"};function s(p,t,_,i,l,d){return a(),r("div",null,t[0]||(t[0]=[n('<h1 id="计算机网络的概念" tabindex="-1">计算机网络的概念 <a class="header-anchor" href="#计算机网络的概念" aria-label="Permalink to &quot;计算机网络的概念&quot;">​</a></h1><br><p>一般认为，计算机网络是一个将众多分散的、自治的计算机系统，通过通信设备与线路连接起来，由功能完善的软件实现资源共享和信息传递的系统。</p><br><p>计算机网络由若干<strong>结点</strong>（Node）和连接这些节点的<strong>链路</strong>（Link）组成。</p><p>网络中的节点可以是计算机、集线器、交换机或路由器等。网络之间还可通过路由器互连，构成一个覆盖范围更广的计算机网络，这样的网络称为互连网（internet）。于是，我们可以这样理解：网络把许多计算机连在一起，而互连网则把许多网络通过路由器连在一起。</p><br><p>注意区分：<strong>internet</strong> 和 <strong>Internet</strong></p><ul><li><p><strong>internet</strong>（互连网）是一个通用名词，泛指由多个计算机网络互连而成的计算机网络。在这些网络之间可以使用任意的通信协议作为通信规则，不一定非要使用 TCP/IP。</p></li><li><p><strong>Internet</strong>（互联网或因特网）则是一个专用名词，指当前全球最大的、开放的、由众多网络和路由器互连而成的特定计算机网络，它采用 TCP/IP 族作为通信规则。</p></li></ul>',9)]))}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
